-- PostgreSQL reference schema; SQLAlchemy creates equivalent tables automatically.
CREATE TABLE customers (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, segment VARCHAR(30) NOT NULL, region VARCHAR(40) NOT NULL);
CREATE TABLE products (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, category VARCHAR(50) NOT NULL);
CREATE TABLE sales (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, external_id VARCHAR(60) NOT NULL UNIQUE, order_date DATE NOT NULL, customer_id INTEGER NOT NULL REFERENCES customers(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity > 0), unit_price NUMERIC(12,2) NOT NULL CHECK(unit_price >= 0));
CREATE INDEX idx_sales_order_date ON sales(order_date);
